mapper.select:
select distinct aa.* from( SELECT I.OURTRADERNAME ourTradeName, decode(I.BUSINESSTYPE,'T01',(select TRADE_MARKET from fin_product where FINPROD_market_ID = I.SECURITYID),'T02',decode(tr.market, 'IB', '01', 'SH', '03', 'SZ', '04')) market, decode(I.BUSINESSTYPE,'T01',ts.SETTLE_SPEED,'T02',tr.SETTLE_SPEED) settleSpeed, I.ourdepositaccountname, I.OURDEPOSITACCOUNTNUMBER ,I.EXECID execid ,I.BUSINESSTYPE businesstype ,decode(I.BUSINESSTYPE,'T01',I.SECURITYID,'T02','') securityid ,decode(I.BUSINESSTYPE, 'T01', I.SYMBOL, 'T02', '') symbol ,I.SIDE side ,ts.Prinamt prinamt ,tr.Repoamt repoamt ,decode(I.BUSINESSTYPE,'T01',ts.Prinamt,'T02',tr.Repoamt) lastqty ,decode(I.BUSINESSTYPE,'T01',I.PRICE,'T02',I.PRICE*100) price ,decode(I.BUSINESSTYPE, 'T01', I.DIRTYPRICE, 'T02', null) dirtyprice ,decode(I.BUSINESSTYPE, 'T01', I.UNDERLYINGYIELD2*100, 'T02', null) underlyingyield2 ,I.TRADEDATE tradedate ,decode(I.BUSINESSTYPE, 'T01', I.ACCRUEDINTERESTAMT, 'T02', null) accruedinterestamt ,I.ACCRUEDINTERESTTOTALAMT accruedinteresttotalamt ,I.TRADECASHAMT tradecashamt ,decode(I.BUSINESSTYPE, 'T01', null, 'T02', I.SETTLCURRAMT2) settlcurramt2 ,decode(I.BUSINESSTYPE, 'T01', null, 'T02', I.TRADELIMITDAYS) tradelimitdays ,decode(I.BUSINESSTYPE, 'T01', null, 'T02', I.CASHHOLDINGDAYS) cashholdingdays ,round(decode(I.BUSINESSTYPE, 'T01', (NVL(I.LASTQTY,0)-NVL(ts.Prinamt,0))/NVL(I.LASTQTY,0), 'T02',(NVL(I.LASTQTY,0)-NVL(tr.Repoamt,0))/NVL(I.LASTQTY,0)),4) percent, decode(I.BUSINESSTYPE, 'T01', I.STRIKEYIELD*100, 'T02', null) strikeyield, CASE WHEN TRD.F_TRADE_ID IS NULL and WFL.F_TRADE_ID is null THEN '02' WHEN ((TRD.F_TRADE_ID IS NOT NULL OR WFL.F_TRADE_ID is NOT null) AND decode(I.BUSINESSTYPE,'T01',ts.Prinamt,'T02',tr.Repoamt)=0) then '01' ELSE '03' END matchStatus FROM INTERF_CSTP_TRADE I LEFT JOIN TRD_PRODUCT_DEAL TRD ON TRD.F_TRADE_ID = I.EXECID AND TRD.IS_CANCEL = #{IS_CANCEL} AND TRD.TRADE_STATUS=01 LEFT JOIN TRD_PRODUCT_DEAL_ADD TADD ON TRD.TRADE_ID = TADD.TRADE_ID LEFT JOIN PTL_PORTFOLIO P ON TADD.PORTFOLIO_ID = P.PORTFOLIO_ID LEFT JOIN WFL_TRD_PRODUCT_DEAL WFL ON WFL.F_TRADE_ID = I.EXECID AND WFL.IS_CANCEL = #{IS_CANCEL} AND WFL.TRADE_STATUS=01 LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD WADD ON WFL.TRADE_ID = WADD.TRADE_ID LEFT JOIN PTL_PORTFOLIO WP ON WADD.PORTFOLIO_ID = WP.PORTFOLIO_ID left join INTERF_OPICS_TRAD_REPO tr on tr.oritradeid = I.EXECID left join INTERF_TRAD_SECDEAL ts on ts.FEDEALNO = EXECID
AND I.BUSINESSTYPE in ('T01','T02')
AND I.BUSINESSTYPE = #{finprodType}
AND I.SIDE = #{ps}
AND I.SECURITYID = #{finprodId}
AND I.EXECID IN
#{item}
AND (TRADEDATE BETWEEN #{tradeDateBegin} AND #{tradeDateEnd})
AND to_date(TRADEDATE,'yyyy-mm-dd') >= to_date(#{entrustStartDate},'yyyy-mm-dd') AND to_date(TRADEDATE,'yyyy-mm-dd') <= to_date(#{entrustEndDate},'yyyy-mm-dd')
and I.OURDEPOSITACCOUNTNUMBER = #{secAcctId}
and I.OURTRADERNAME LIKE CONCAT('%',CONCAT(#{ourTradeName},'%'))
) aa
AND aa.matchStatus IN
#{item}
and market = #{tradeMarket}
and settleSpeed = #{settleSpeed}
and tradelimitdays = #{tradelimitdays}
